mapper.select:
SELECT p.*, (SELECT COUNT(*) FROM sys_tenant_package_permission tpp INNER JOIN sys_permission perm ON perm.id = tpp.permission_id AND perm.is_deleted = 0 WHERE tpp.package_id = p.id AND tpp.is_deleted = 0 AND perm.type IN ('menu', 'button')) AS permission_count FROM sys_tenant_package p WHERE p.is_deleted = 0
AND (p.name LIKE CONCAT('%', #{request.keyword}, '%') OR p.code LIKE CONCAT('%', #{request.keyword}, '%'))
AND p.status = #{request.status}
ORDER BY permission_count ${request.safeSortOrder()}
ORDER BY p.${request.safeSortField()} ${request.safeSortOrder()}
ORDER BY p.sort ASC
